-- The two checklists published on 2026-11-12: Making the Call You Keep
-- Putting Off (Phone Calls) and Going Through Menopause (Menopause).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-12`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('making-the-call-you-keep-putting-off', 'Making the Call You Keep Putting Off', 'For a phone call you have been avoiding for days. It writes the first sentence down, puts a real time in the calendar, gets your details ready before you dial, keeps a note of who you spoke to, and puts something pleasant straight after.', 'Phone Calls', '["Write the first sentence and read it off the page — openings are where calls get abandoned.", "Put the call in the calendar with a time — an undated task simply moves to tomorrow.", "Call early in the day rather than at the end — a call you dread grows all afternoon.", "Have your account number and dates ready — hunting mid-call is what makes it feel awful.", "Stand up and walk while you talk — your voice carries differently when you are not hunched.", "Say what you want in the first thirty seconds — a clear ask gets routed faster than a story.", "Write down who you spoke to and when — a name and a time saves the next call entirely.", "Leave a voicemail rather than hanging up — a second attempt is harder than a first.", "Do one small pleasant thing straight after — the relief is the only reliable reward here."]'::jsonb, 'as needed', array['Anxiety', 'Habits', 'Stress']::text[], 1, '2026-11-12T16:00:00+00:00'::timestamptz),
  ('going-through-menopause', 'Going Through Menopause', 'For the years around menopause, when the changes are real and the advice is thin. It keeps notes worth taking to an appointment, sorts the bedroom and the layers, gets one person at work told, and finds somebody else going through it.', 'Menopause', '["Write down what you notice and when — a few weeks of notes make an appointment worth having.", "Ask the doctor what your options actually are — there is more than one approach and you can ask.", "Keep the bedroom cold and the layers light — the night is where most of this is won or lost.", "Put a change of clothes where you will need one — a plan takes the panic out of a flush.", "Tell one person at work what is going on — needing a window open is easier once it is said.", "Move your body in a way you do not dread — the kind you keep doing is the kind that counts.", "Name the mood swing out loud as it arrives — saying it takes some of the blame off everyone.", "Find one other person going through it — this gets smaller once it stops being private.", "Treat the fog as temporary and write things down — lists carry what memory is not carrying now."]'::jsonb, 'weekly', array['Body', 'Sleep', 'Self-Care']::text[], 1, '2026-11-12T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
